command:
// Öffnet das Wildnisreise-Fenster.
//
// Das Fenster ist für alle da: Spieler sehen denselben Reisetag, dieselbe
// Mondphase und dieselben Würfe, können aber nur ihre eigenen Charaktere
// steuern. Es ist also unbedenklich, dieses Makro auf die gemeinsame
// Hotbar zu legen.
const api = game.modules.get("toa-adventure-tracker")?.api;

if (!api) {
  ui.notifications.error("Das Modul 'Wildnisreise' ist nicht aktiv.");
} else {
  api.open();
}

